solution.javascript:
function leastInterval(tasks, n) {
  const count = {};
  for (const t of tasks) count[t] = (count[t] || 0) + 1;
  const max = Math.max(...Object.values(count));
  const numMax = Object.values(count).filter(c => c === max).length;
  return Math.max(tasks.length, (max - 1) * (n + 1) + numMax);
}

