int leastInterval(vector<char>& tasks, int n) {
    vector<int> count(26);
    for (char c : tasks) count[c-'A']++;
    int maxCnt = *max_element(count.begin(), count.end());
    int numMax = count_if(count.begin(), count.end(), [maxCnt](int x){ return x == maxCnt; });
    return max((int)tasks.size(), (maxCnt - 1) * (n + 1) + numMax);
}
